printf '%s\n' '--- execution directory ownership ---'
for d in $(printf '%s' "$PATH" | tr : ' '); do if [ -d "$d" ]; then stat -c '%A %U:%G %n' "$d"; else stat -c '%A %U:%G %n' "$d"; fi; done
printf '%s\n' '--- runner service config metadata (credential values omitted) ---'
python3 - <<'PY'
import json
from pathlib import Path
for name in ['.runner','.credentials']:
    p=Path('/home/runner/actions-runner')/name
    d=json.loads(p.read_text(encoding='utf-8-sig'))
    def redact(obj):
        if isinstance(obj,dict):
            return {k: ('<redacted>' if any(x in k.lower() for x in ('token','secret','key','credential','password','data')) else redact(v)) for k,v in obj.items()}
        if isinstance(obj,list): return [redact(v) for v in obj]
        return obj
    print(name, redact(d))
    if isinstance(d,dict):
        for k,v in d.items():
            if isinstance(v,dict): print(k, 'fields:', list(v))
PY
printf '%s\n' '--- work files ---'
find /home/runner/actions-runner/_work -maxdepth 5 -type f \( -name config -o -name '*.sh' -o -name '*.json' \) -print | head -100
printf '%s\n' '--- listener log tail ---'
find /home/runner/actions-runner/_diag -maxdepth 1 -type f -name 'Runner_*.log' -print0 | xargs -0 tail -n 80
